"""RoboPaint camera-guided acrylic copy; all motion goes through the public Robot client."""
import sys, os, json, time, numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
r=Robot()
Q=[0,1,0,0]
LOG='/app/output/actions.jsonl'
last=np.array(r.get_obs(cameras=[]).meta['proprio']['now'][7:10])
def submit(P,cameras=[]):
 global last
 P=np.array(P,float)
 for i in range(0,len(P),190):
  chunk=P[i:i+190]
  before=r.status()
  try:res=r.submit('ee_pose',chunk,dt=.05,cameras=cameras,video='none')
  except Exception:
   status=r.wait_ready()
   if status['control_steps']==before['control_steps']:
    res=r.submit('ee_pose',chunk,dt=.05,cameras=cameras,video='none')
   else:raise RuntimeError('Uncertain motion execution; inspect status')
  with open(LOG,'a') as f:f.write(json.dumps({'poses':chunk.tolist(),'meta':res.meta})+'\n')
  if res.meta.get('plan'):print('PLAN',res.meta['plan'],flush=True)
  last=chunk[-1,:3].copy()
 return res
def move(p,speed=.12,hold=0):
 global last
 p=np.array(p,float); n=max(1,int(np.ceil(np.linalg.norm(p-last)/speed/.05)))
 P=[np.r_[last+(p-last)*t,Q] for t in np.linspace(1/n,1,n)]
 P += [np.r_[p,Q]]*int(hold/.05)
 return submit(P)
def dip(c):
 x=-.16+.03*(c%5); y=.145 if c<5 else .175
 move([last[0],last[1],.075]);move([x,y,.075]);move([x,y,.024],.05,.3);move([x,y,.065],.05)
def observe(name):
 o=r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True)
 o.save('/app/output/'+name)
 for c,a in o.last.items():Image.fromarray(a).save('/app/output/'+name+'_'+c+'.png')
 return o

def practice():
 dip(9)
 for i,depth in enumerate([.0005,.001,.002,.004,.006,.009,.012]):
  x=-.015-.028*i;y=-.208
  move([x,y,.05]);move([x,y,.0202-depth],.025,.25)
  move([x,-.163,.0202-depth],.02,.2)
  move([x,-.163,.05],.025)
 move([-.1,.19,.10]);observe('practice1')
if __name__=='__main__':
 if len(sys.argv)>1 and sys.argv[1]=='practice':practice()
PY
